    int hour = (int) (timeBucket - year * 100000000L - month * 10000L - day * 100L);
    int minute = (int) (timeBucket - year * 100000000L - month * 10000L - day * 100L - hour * 10L);
    int second = (int) (timeBucket - year * 100000000L - month * 10000L - day * 100L - hour * 10L - minute * 1L);

    int compressedYear = year + dayStep / 365;
    int compressedMonth = month + (dayStep % 365) / 30;
    int compressedDay = day + (dayStep % 30);
    int compressedHour = hour;
    int compressedMinute = minute;
    int compressedSecond = second;

    return (compressedYear * 100000000L + compressedMonth * 10000L + compressedDay * 100L + compressedHour * 10L + compressedMinute * 1L + compressedSecond);
}

