    if (str == null) {
        return null;
    }

    // Create a new string builder to build our unescaped string
    StringBuilder sb = new StringBuilder();

    // Loop through each character in the input string
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);

        // If we encounter a backslash, check if it's preceded by another backslash
        if (c == '\\' && i > 0 && str.charAt(i - 1) == '\\') {
            // If it is, append the current character as is
            sb.append(c);
        } else if (c == 'n') {
            // If the character is a newline, append a newline character
            sb.append('\n');
        } else if (c == 'r') {
            // If the character is a carriage return, append a carriage return character
            sb.append('\r');
        } else if (c == 't') {
            // If the character is a tab character, append a tab character
            sb.append('\t');
        } else if (c == 'b') {
            // If the character is a backspace character, append a backspace character
            sb.append('\b');
        } else if (c == 'f') {
            // If the character is a formfeed character, append a formfeed character
            sb.append('\f');
        } else if (c == '"') {
            // If the character is a double quote character, append a double quote character
            sb.append('"');
        } else if (c == '\'') {
            // If the character is a single quote character, append a single quote character
            sb.append('\'');
        } else {
            // If none of the above, append the current character as is
            sb.append(c);
        }
    }

    return sb.toString();
}

